92	pub fn help_text(feedback: bool) -> String {
93	    format!(
94	        "xerj share — give someone read-only search over one indexed folder: a link, a\n\
95	         passcode, an expiry\n\
96	         \n\
97	         The guest opens the link, types the passcode, and gets a reading room over\n\
98	         that one index: search, highlighted snippets, a document view. Read-only.\n\
99	         The documents stay on this machine: XERJ copies them nowhere, and this node\n\
100	         answers the guest's browser. With --tunnel that traffic passes through\n\
101	         Cloudflare, which can read it, and what Cloudflare keeps of what it carries\n\
102	         is between you and Cloudflare (see --tunnel). Revoke any time.\n\
103	         \n\
104	         {}\
105	         USAGE:\n\
106	             xerj share <index|folder> [OPTIONS]   create a share\n\
107	             xerj share --list                     every share on this node\n\
108	             xerj share --revoke <handle>          end one (kills its guest keys)\n\
109	         \n\
110	         <index|folder>: an index name (`ax-notes`, or `a,b`), or the folder you gave\n\
111	         `xerj brain` — that resolves to the brain and indices it built.\n\
112	         \n\
113	         OPTIONS:\n\
114	             --expires <D>      lifetime: 30m, 24h, 7d … (default {}; longest 30d)\n\
115	             --max-claims <N>   how many times the link can be opened (default {},\n\
116	                                most {}). Each open mints its own guest key. One\n\
117	                                open is one browser tab: a guest who closes the tab\n\
118	                                needs another open to come back — give a few to\n\
119	                                someone who will read over several days\n\
120	             --passcode <CODE>  choose the passcode ({}–{} chars). Default: a generated\n\
121	                                xxxx-xxxx. A passcode typed here lands in your shell\n\
122	                                history; the generated one does not\n\
123	             --label <TEXT>     what the guest sees as the title (e.g. \"for Dana\")\n\
124	             --brain <NAME>     also share this brain's links (a folder argument sets\n\
125	                                this for you)\n\
126	             --index            treat the argument as an index name even when a folder\n\
127	                                of that name exists here\n\
128	             --tunnel           open a temporary public address with `cloudflared`, print\n\
129	                                the full guest link, run until Ctrl-C, then close the\n\
130	                                tunnel and revoke the share. Without `cloudflared`\n\
131	                                installed you get install steps and the local link.\n\
132	                                The tunnel is Cloudflare's: it ends TLS there, so\n\
133	                                Cloudflare can read what passes through — the\n\
134	                                passcode, the guest's key, the searches and every\n\
135	                                document the guest opens.\n\
136	                                If that is not acceptable, use --public-url with\n\
137	                                your own certificate\n\
138	             --keep             with --tunnel: leave the share active after Ctrl-C\n\
139	             --public-url <U>   the https:// address this node is reachable at (your own\n\
140	                                hostname or reverse proxy); the printed link uses it.\n\
141	                                http:// is accepted with a warning: the passcode and\n\
142	                                the guest's key would cross the network unencrypted\n\
143	             --url <U>          the node, scheme included (default http://localhost:9200)\n\
144	             --data-dir <PATH>  where the node's admin.key is (default ~/.xerj/brain)\n\
145	             --api-key <K>      the node's ADMIN key (or env XERJ_API_KEY). Shares can\n\
146	                                only be managed with the admin key\n\
147	             --json             machine-readable output\n\
148	             --disable-feedback do not print the feedback invitation above (env\n\
149	                                XERJ_DISABLE_FEEDBACK=true)\n\
150	             --help, -h         this help\n\
151	         \n\
152	         REFUSES against a node running with --insecure / auth off: every request is\n\
153	         already the superuser there, so a read-only guest key would restrict nothing.\n\
154	         \n\
155	         EXIT CODES: 0 ok; 1 refused or failed; 2 usage; 130 interrupted before the tunnel\n\
156	         was up (nothing was shared)\n",
157	        xerj_common::feedback::block(feedback),
158	        xerj_api::share::DEFAULT_EXPIRES_IN,
159	        xerj_api::share::DEFAULT_MAX_CLAIMS,
160	        xerj_api::share::MAX_MAX_CLAIMS,
161	        xerj_api::share::MIN_PASSCODE_CHARS,
162	        xerj_api::share::MAX_PASSCODE_CHARS,
163	    )
164	}
