468	/// How the printed link reaches this node. It decides what the owner is told
469	/// about who else can read the traffic — see the module docs.
470	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
471	pub enum Reach {
472	    /// The node's own URL, and the host is loopback: only this machine.
473	    Loopback,
474	    /// The node's own URL, and the host is NOT loopback — a LAN or public
475	    /// address. The first cut called this "only this machine can reach" too,
476	    /// because it looked at the flags and not at the URL.
477	    Direct,
478	    /// `--public-url`: the owner's hostname or reverse proxy.
479	    PublicUrl,
480	    /// `--tunnel`: a Cloudflare quick tunnel, which terminates TLS.
481	    CloudflareTunnel,
482	}
483	
484	impl Reach {
485	    /// The `via` field of `--json` output.
486	    fn as_str(self) -> &'static str {
487	        match self {
488	            Reach::Loopback => "loopback",
489	            Reach::Direct => "direct",
490	            Reach::PublicUrl => "public_url",
491	            Reach::CloudflareTunnel => "cloudflare_tunnel",
492	        }
493	    }
494	}
495	
496	/// What a quick tunnel means for the traffic, in the words the owner reads
497	/// before sending the link. One constant: the human banner, `--json`
498	/// (`transit_notice`) and the tests all use it.
499	pub const CLOUDFLARE_TRANSIT_NOTICE: &str =
500	    "this link goes through Cloudflare. A quick tunnel ends TLS at Cloudflare, so Cloudflare \
501	     can read everything that passes through it: the passcode, the guest's key, the searches \
502	     and every document the guest opens. If that is not acceptable, \
503	     publish the node under your own certificate and use --public-url instead";
504	
505	/// The host part of an `http(s)://host[:port]/…` URL, brackets kept.
506	fn url_host(url: &str) -> Option<&str> {
507	    let rest = url
508	        .strip_prefix("http://")
509	        .or_else(|| url.strip_prefix("https://"))?;
510	    let hostport = rest.split(['/', '?', '#']).next().unwrap_or(rest);
511	    let host = match hostport.strip_prefix('[') {
512	        // [::1]:9200
513	        Some(v6) => v6.split(']').next().unwrap_or(v6),
514	        None => hostport.rsplit_once(':').map_or(hostport, |(h, _)| h),
515	    };
516	    (!host.is_empty()).then_some(host)
517	}
518	
519	/// Does `url` name this machine and nothing else?
520	fn is_loopback_url(url: &str) -> bool {
521	    match url_host(url) {
522	        Some("localhost") => true,
523	        Some(host) => host
524	            .parse::<std::net::IpAddr>()
525	            .is_ok_and(|ip| ip.is_loopback()),
526	        None => false,
527	    }
528	}
529	
530	/// How the link for this create reaches the node.
531	fn reach_of(tunnel_up: bool, public_url: Option<&str>, node_url: &str) -> Reach {
532	    if tunnel_up {
533	        Reach::CloudflareTunnel
534	    } else if public_url.is_some() {
535	        Reach::PublicUrl
536	    } else if is_loopback_url(node_url) {
537	        Reach::Loopback
538	    } else {
539	        Reach::Direct
540	    }
541	}
