642	/// Find `cloudflared`: `XERJ_CLOUDFLARED`, then `PATH`, then `~/.local/bin`
643	/// (where the install steps above put it, and which a non-login shell often
644	/// does not have on `PATH`).
645	fn find_cloudflared() -> Option<PathBuf> {
646	    if let Some(p) = std::env::var_os("XERJ_CLOUDFLARED").filter(|s| !s.is_empty()) {
647	        let p = PathBuf::from(p);
648	        return p.is_file().then_some(p);
649	    }
650	    let exe = if cfg!(windows) {
651	        "cloudflared.exe"
652	    } else {
653	        "cloudflared"
654	    };
655	    let mut dirs: Vec<PathBuf> = std::env::var_os("PATH")
656	        .map(|p| std::env::split_paths(&p).collect())
657	        .unwrap_or_default();
658	    if let Some(home) = std::env::var_os("HOME") {
659	        dirs.push(Path::new(&home).join(".local").join("bin"));
660	    }
661	    dirs.into_iter().map(|d| d.join(exe)).find(|p| p.is_file())
662	}
