686	/// The words for the refusal. One place, so the CLI probe and the server's
687	/// `409` say the same thing.
688	fn open_mode_refusal(url: &str) -> String {
689	    format!(
690	        "the node at {url} is running with authentication OFF (--insecure, or \
691	         auth.enabled = false).\n\
692	         \x20 A share is a read-only guest key. On a node with auth off every request is \
693	         already\n\
694	         \x20 the superuser, so that key would restrict nothing: the guest — and anyone \
695	         else who\n\
696	         \x20 can reach the port — could read, change and delete every index without it.\n\
697	         \x20 Restart the node without --insecure (auth is on by default; the admin key is \
698	         written\n\
699	         \x20 to <data_dir>/admin.key), then run this again."
700	    )
701	}
