848	/// What a folder argument resolved to.
849	struct Resolved {
850	    indices: Vec<String>,
851	    brain: Option<String>,
852	    /// A line for the owner: how the argument became these indices.
853	    how: Option<String>,
854	}
855	
856	/// What the brain-meta lookup for a folder argument came back with.
857	#[derive(Debug, PartialEq)]
858	enum BrainMeta {
859	    Found(Value),
860	    /// The node answered and there is no such brain.
861	    NotIndexed,
862	    /// The node did not answer the question — most often `401`/`403`, a wrong
863	    /// or non-admin key.
864	    Refused,
865	}
866	
867	/// Read a `GET /{edges}/_doc/__brain_meta__` answer.
868	///
869	/// This went through `Es::get_doc`, which turns *every* body without
870	/// `found: true` into "no document" — including a `401`. So a wrong key with a
871	/// folder argument was reported as "<folder> has not been indexed … run `xerj
872	/// brain` first", sending the owner to re-index a folder that was indexed all
873	/// along, while the same key with an index argument got the right sentence
874	/// (review of PR #947). Only a `404`, or a `200` that says `found: false`,
875	/// means the brain is not there.
876	fn brain_meta(status: u16, body: &Value) -> BrainMeta {
877	    match status {
878	        200 if body.get("found").and_then(Value::as_bool) == Some(true) => body
879	            .get("_source")
880	            .cloned()
881	            .map_or(BrainMeta::NotIndexed, BrainMeta::Found),
882	        200 | 404 => BrainMeta::NotIndexed,
883	        _ => BrainMeta::Refused,
884	    }
885	}
886	
887	fn resolve_target(es: &Es, common: &Common, create: &CreateCfg) -> Result<Resolved> {
888	    let target = classify_target(&create.target, create.force_index, |p| p.is_dir())
889	        .map_err(|e| anyhow!(e))?;
890	    match target {
891	        Target::Indices(indices) => Ok(Resolved {
892	            indices,
893	            brain: create.brain.clone(),
894	            how: None,
895	        }),
896	        Target::Folder(folder) => {
897	            let brain = match &create.brain {
898	                Some(b) => b.clone(),
899	                None => {
900	                    let derived = xerj_autoindex::derive_brain_name(&folder);
901	                    detect::validate_brain(&derived).map_err(|reason| {
902	                        anyhow!(
903	                            "folder name '{derived}' is not usable as a brain name ({reason}) — \
904	                             pass the one you used with --brain <name>"
905	                        )
906	                    })?;
907	                    derived
908	                }
909	            };
910	            let edges_index = detect::edges_index_name(&brain);
911	            let (status, body) = es
912	                .request_json(
913	                    "GET",
914	                    &format!("/{edges_index}/_doc/{}", detect::BRAIN_META_ID),
915	                    None,
916	                )
917	                .with_context(|| format!("look up brain '{brain}'"))?;
918	            let meta = match brain_meta(status, &body) {
919	                BrainMeta::Found(meta) => meta,
920	                BrainMeta::NotIndexed => bail!(
921	                    "{} has not been indexed on this node: there is no brain named '{brain}'. \
922	                     Run `xerj brain {}` first, or pass an index name",
923	                    folder.display(),
924	                    folder.display()
925	                ),
926	                BrainMeta::Refused => return Err(explain(status, &body, common)),
927	            };
928	            let indices: Vec<String> = meta
929	                .get("nodes_index")
930	                .and_then(Value::as_str)
931	                .unwrap_or("")
932	                .split(',')
933	                .map(str::trim)
934	                .filter(|s| !s.is_empty())
935	                .map(String::from)
936	                .collect();
937	            if indices.is_empty() {
938	                bail!(
939	                    "brain '{brain}' does not record which indices hold its documents (it \
940	                     predates that field). Share by index name instead — `xerj autoindex \
941	                     map` lists them"
942	                );
943	            }
944	            let how = format!(
945	                "{} → brain '{brain}' → {}",
946	                folder.display(),
947	                indices.join(", ")
948	            );
949	            Ok(Resolved {
950	                indices,
951	                brain: Some(brain),
952	                how: Some(how),
953	            })
954	        }
955	    }
956	}
