958	fn create_share(es: &Es, common: &Common, create: &CreateCfg) -> Result<i32> {
959	    let resolved = resolve_target(es, common, create)?;
960	    if let Some(how) = &resolved.how {
961	        eprintln!("sharing {how}");
962	    }
963	
964	    // The tunnel comes up BEFORE the share exists, so a link is never printed
965	    // for an address that is not there, and a tunnel that cannot start costs
966	    // nothing but a message.
967	    let mut tunnel: Option<Tunnel> = None;
968	    let mut tunnel_note: Option<String> = None;
969	    // Listening before the tunnel exists — see `Interrupts`.
970	    let interrupts = create.tunnel.then(Interrupts::listen);
971	    if create.tunnel {
972	        let (_, port) = local_http_origin(&common.url).map_err(|e| anyhow!(e))?;
973	        match find_cloudflared() {
974	            None => {
975	                tunnel_note = Some(format!(
976	                    "--tunnel needs `cloudflared`, which is not installed (looked on PATH and \
977	                     in ~/.local/bin).\n{}\n  then run this command again. Until then the \
978	                     link above only works on this machine.",
979	                    cloudflared_install_help()
980	                ));
981	            }
982	            Some(bin) => {
983	                eprintln!("opening a tunnel with {} …", bin.display());
984	                let opened = Tunnel::open(
985	                    &bin,
986	                    port,
987	                    interrupts.as_ref().expect("listening when --tunnel is set"),
988	                );
989	                match opened {
990	                    Ok(t) => tunnel = Some(t),
991	                    Err(OpenError::Interrupted(why)) => {
992	                        eprintln!("{why} before the tunnel was up — nothing was shared.");
993	                        return Ok(130);
994	                    }
995	                    Err(OpenError::Failed(e)) => {
996	                        tunnel_note = Some(format!(
997	                            "the tunnel did not come up: {e:#}\n  the link above only works on \
998	                             this machine."
999	                        ))
1000	                    }
1001	                }
1002	            }
1003	        }
1004	    }
1005	
1006	    let mut body = json!({ "index": resolved.indices });
1007	    if let Some(b) = &resolved.brain {
1008	        body["brain"] = json!(b);
1009	    }
1010	    if let Some(e) = &create.expires {
1011	        body["expires_in"] = json!(e);
1012	    }
1013	    if let Some(n) = create.max_claims {
1014	        body["max_claims"] = json!(n);
1015	    }
1016	    if let Some(p) = &create.passcode {
1017	        body["passcode"] = json!(p);
1018	    }
1019	    if let Some(l) = &create.label {
1020	        body["label"] = json!(l);
1021	    }
1022	    let (status, resp) = es.request_json("POST", "/_share", Some(&body))?;
1023	    if status != 200 {
1024	        return Err(explain(status, &resp, common));
1025	    }
1026	    let share_id = resp
1027	        .get("share_id")
1028	        .and_then(Value::as_str)
1029	        .context("the node's response carries no share_id")?;
1030	    let handle = resp.get("handle").and_then(Value::as_str).unwrap_or("");
1031	    let url_path = resp.get("url_path").and_then(Value::as_str);
1032	
1033	    let base = tunnel
1034	        .as_ref()
1035	        .map(|t| t.public_url.clone())
1036	        .or_else(|| create.public_url.clone())
1037	        .unwrap_or_else(|| common.url.clone());
1038	    let link = guest_link(&base, url_path, share_id);
1039	    let reach = reach_of(tunnel.is_some(), create.public_url.as_deref(), &common.url);
1040	
1041	    if common.json {
1042	        let mut out = resp.clone();
1043	        out["link"] = json!(link);
1044	        out["local_only"] = json!(reach == Reach::Loopback);
1045	        out["via"] = json!(reach.as_str());
1046	        if reach == Reach::CloudflareTunnel {
1047	            out["transit_notice"] = json!(CLOUDFLARE_TRANSIT_NOTICE);
1048	        }
1049	        out["revoke"] = json!(format!(
1050	            "xerj share --revoke {handle}{}",
1051	            connection_args(common)
1052	        ));
1053	        println!("{}", serde_json::to_string_pretty(&out)?);
1054	    } else {
1055	        print!("{}", render_created(&resp, &link, reach, common));
1056	    }
1057	    if let Some(note) = &tunnel_note {
1058	        eprintln!("\n{note}");
1059	    }
1060	
1061	    let Some(tunnel) = tunnel else {
1062	        return Ok(0);
1063	    };
1064	    if resp
1065	        .pointer("/claim_limiter/source_address")
1066	        .and_then(Value::as_str)
1067	        == Some("peer")
1068	    {
1069	        eprintln!(
1070	            "\nnote: through a tunnel every guest reaches this node from 127.0.0.1, so the \
1071	             audit log\n      records that address for them. To record each guest's real \
1072	             address, add\n        trusted_proxies = [\"127.0.0.1\", \"::1\"]\n      under \
1073	             [server] in the node's config and restart it. The passcode lockout\n      \
1074	             ({} guesses per share per hour) holds either way.",
1075	            xerj_api::share::SHARE_PER_HOUR
1076	        );
1077	    }
1078	    eprintln!(
1079	        "\ntunnel is up — keep this running while your guest reads. Ctrl-C closes the tunnel{}.",
1080	        if create.keep {
1081	            " (the share stays active: --keep)"
1082	        } else {
1083	            " and revokes the share"
1084	        }
1085	    );
1086	    let why = tunnel.wait(interrupts.as_ref().expect("listening when --tunnel is set"));
1087	    eprintln!("\n{why} — closing the tunnel.");
1088	    if why == CLOUDFLARED_STOPPED {
1089	        // Nobody asked it to stop: its own last words are the only reason.
1090	        let tail = tunnel_log_tail(&tunnel.log);
1091	        if !tail.is_empty() {
1092	            eprintln!("{}", tail.trim_start_matches('\n'));
1093	        }
1094	    }
1095	    drop(tunnel);
1096	    if create.keep {
1097	        eprintln!(
1098	            "the share is still active on this node until it expires. End it: xerj share \
1099	             --revoke {handle}{}",
1100	            connection_args(common)
1101	        );
1102	        return Ok(0);
1103	    }
1104	    match es.request_json("DELETE", &format!("/_share/{handle}"), None) {
1105	        Ok((200, body)) => eprintln!(
1106	            "share {handle} revoked — {} guest key(s) invalidated.",
1107	            body.get("keys_invalidated")
1108	                .and_then(Value::as_u64)
1109	                .unwrap_or(0)
1110	        ),
1111	        Ok((status, _)) => eprintln!(
1112	            "could not revoke share {handle} (HTTP {status}). Do it by hand: xerj share \
1113	             --revoke {handle}{}",
1114	            connection_args(common)
1115	        ),
1116	        Err(e) => eprintln!(
1117	            "could not revoke share {handle} ({e:#}). Do it by hand: xerj share --revoke \
1118	             {handle}{}",
1119	            connection_args(common)
1120	        ),
1121	    }
1122	    Ok(0)
1123	}
