1125	/// The connection flags a follow-up command has to repeat to reach the same
1126	/// node: `--url` and `--data-dir`, each only when it is not the default. Never
1127	/// `--api-key` — a key is not something to echo back into a terminal
1128	/// scrollback, and `--data-dir` (or `XERJ_API_KEY`) already supplies it.
1129	fn connection_args(common: &Common) -> String {
1130	    let mut out = String::new();
1131	    if common.url != DEFAULT_URL {
1132	        out.push_str(&format!(" --url {}", sh_quote(&common.url)));
1133	    }
1134	    if let Some(dir) = &common.data_dir {
1135	        out.push_str(&format!(
1136	            " --data-dir {}",
1137	            sh_quote(&dir.display().to_string())
1138	        ));
1139	    }
1140	    out
1141	}
