1274	/// Greedy word wrap at `width`, continuation lines prefixed with `indent`.
1275	fn wrap(text: &str, width: usize, indent: &str) -> String {
1276	    let mut out = String::new();
1277	    let mut line = 0usize;
1278	    for word in text.split_whitespace() {
1279	        let n = word.chars().count();
1280	        if line > 0 && line + 1 + n > width {
1281	            out.push('\n');
1282	            out.push_str(indent);
1283	            line = 0;
1284	        } else if line > 0 {
1285	            out.push(' ');
1286	            line += 1;
1287	        }
1288	        out.push_str(word);
1289	        line += n;
1290	    }
1291	    out
1292	}
