1382	/// Why a tunnel did not open. The two cases end differently: an interrupt
1383	/// stops the command with nothing shared; a failure falls back to the local
1384	/// link.
1385	enum OpenError {
1386	    Interrupted(&'static str),
1387	    Failed(anyhow::Error),
1388	}
1389	
1390	/// How often the wait loops look up from the tunnel's log to check for a
1391	/// signal.
1392	const TICK: Duration = Duration::from_millis(200);
1393	/// What [`Tunnel::wait`] returns when the tunnel went away by itself.
1394	const CLOUDFLARED_STOPPED: &str = "cloudflared stopped";
1395	
1396	impl Tunnel {
1397	    /// Spawn `cloudflared tunnel --url http://127.0.0.1:<port>` and wait for
1398	    /// its hostname. `127.0.0.1`, not `localhost`: the node binds IPv4
1399	    /// loopback by default and `localhost` may resolve to `::1` first.
1400	    fn open(bin: &Path, port: u16, interrupts: &Interrupts) -> Result<Self, OpenError> {
1401	        let failed = |msg: String| OpenError::Failed(anyhow!(msg));
1402	        let mut command = Command::new(bin);
1403	        command
1404	            .args(["tunnel", "--no-autoupdate", "--url"])
1405	            .arg(format!("http://127.0.0.1:{port}"))
1406	            .stdin(Stdio::null())
1407	            .stdout(Stdio::piped())
1408	            .stderr(Stdio::piped());
1409	        // Its own process group: a terminal Ctrl-C goes to the foreground
1410	        // group, and the tunnel must be closed by us, in order — after the
1411	        // wait loop has noticed — not race us to the exit.
1412	        #[cfg(unix)]
1413	        {
1414	            use std::os::unix::process::CommandExt;
1415	            command.process_group(0);
1416	        }
1417	        // Belt and braces on Linux: if this command dies in a way no handler
1418	        // sees (SIGKILL, a panic=abort), the kernel terminates the tunnel.
1419	        // The "parent" here is the spawning *thread*, which is the thread that
1420	        // runs this whole command, so it lives exactly as long as we do.
1421	        #[cfg(target_os = "linux")]
1422	        {
1423	            use std::os::unix::process::CommandExt;
1424	            // SAFETY: `prctl` is async-signal-safe and touches no memory the
1425	            // parent shares; nothing else runs between fork and exec.
1426	            unsafe {
1427	                command.pre_exec(|| {
1428	                    libc::prctl(libc::PR_SET_PDEATHSIG, libc::SIGTERM);
1429	                    Ok(())
1430	                });
1431	            }
1432	        }
1433	        let mut child = command
1434	            .spawn()
1435	            .map_err(|e| failed(format!("start {}: {e}", bin.display())))?;
1436	
1437	        let (tx, rx) = mpsc::channel::<TunnelEvent>();
1438	        let log = TunnelLog::default();
1439	        let mut readers = Vec::new();
1440	        // cloudflared logs to stderr; read stdout too so neither pipe can fill
1441	        // and stall it.
1442	        if let Some(err) = child.stderr.take() {
1443	            readers.push(spawn_reader(err, tx.clone(), log.clone()));
1444	        }
1445	        if let Some(out) = child.stdout.take() {
1446	            readers.push(spawn_reader(out, tx.clone(), log.clone()));
1447	        }
1448	        // When both pipes close, the process is gone.
1449	        std::thread::spawn(move || {
1450	            for r in readers {
1451	                let _ = r.join();
1452	            }
1453	            let _ = tx.send(TunnelEvent::Exited);
1454	        });
1455	
1456	        // From here on `tunnel` owns the child: every early return below drops
1457	        // it, and `Drop` closes the tunnel.
1458	        let mut tunnel = Tunnel {
1459	            child,
1460	            public_url: String::new(),
1461	            events: rx,
1462	            log,
1463	        };
1464	        let deadline = std::time::Instant::now() + TUNNEL_URL_TIMEOUT;
1465	        loop {
1466	            if let Some(why) = interrupts.fired() {
1467	                return Err(OpenError::Interrupted(why));
1468	            }
1469	            match tunnel.events.recv_timeout(TICK) {
1470	                Ok(TunnelEvent::Url(u)) => {
1471	                    tunnel.public_url = u;
1472	                    break;
1473	                }
1474	                Ok(TunnelEvent::Connected) => {}
1475	                Ok(TunnelEvent::Exited) | Err(mpsc::RecvTimeoutError::Disconnected) => {
1476	                    return Err(failed(format!(
1477	                        "cloudflared exited before printing an address{}",
1478	                        tunnel_log_tail(&tunnel.log)
1479	                    )));
1480	                }
1481	                Err(mpsc::RecvTimeoutError::Timeout) => {
1482	                    if std::time::Instant::now() > deadline {
1483	                        return Err(failed(format!(
1484	                            "cloudflared printed no address within {}s (is this machine online?)",
1485	                            TUNNEL_URL_TIMEOUT.as_secs()
1486	                        )));
1487	                    }
1488	                }
1489	            }
1490	        }
1491	        // The hostname is printed before the first edge connection registers;
1492	        // a link opened in that gap gets Cloudflare's 530. Wait for the
1493	        // connection, but not forever — the link is still the right link.
1494	        let deadline = std::time::Instant::now() + TUNNEL_CONNECT_TIMEOUT;
1495	        loop {
1496	            if let Some(why) = interrupts.fired() {
1497	                return Err(OpenError::Interrupted(why));
1498	            }
1499	            match tunnel.events.recv_timeout(TICK) {
1500	                Ok(TunnelEvent::Connected) => break,
1501	                Ok(TunnelEvent::Url(_)) => {}
1502	                Ok(TunnelEvent::Exited) | Err(mpsc::RecvTimeoutError::Disconnected) => {
1503	                    return Err(failed(format!(
1504	                        "cloudflared exited while connecting{}",
1505	                        tunnel_log_tail(&tunnel.log)
1506	                    )));
1507	                }
1508	                Err(mpsc::RecvTimeoutError::Timeout) => {
1509	                    if std::time::Instant::now() > deadline {
1510	                        eprintln!(
1511	                            "cloudflared has an address but has not confirmed a connection \
1512	                             yet; the link may take a few seconds to start answering."
1513	                        );
1514	                        break;
1515	                    }
1516	                }
1517	            }
1518	        }
1519	        Ok(tunnel)
1520	    }
1521	
1522	    /// Block until a signal arrives or `cloudflared` goes away. Returns why.
1523	    fn wait(&self, interrupts: &Interrupts) -> &'static str {
1524	        loop {
1525	            if let Some(why) = interrupts.fired() {
1526	                return why;
1527	            }
1528	            match self.events.recv_timeout(TICK) {
1529	                Ok(TunnelEvent::Exited) | Err(mpsc::RecvTimeoutError::Disconnected) => {
1530	                    return CLOUDFLARED_STOPPED
1531	                }
1532	                _ => {}
1533	            }
1534	        }
1535	    }
1536	}
