1538	impl Drop for Tunnel {
1539	    /// The tunnel never outlives this command: terminate, give it a moment to
1540	    /// deregister from the edge, then kill.
1541	    fn drop(&mut self) {
1542	        #[cfg(unix)]
1543	        {
1544	            // SAFETY: plain `kill(2)` on a pid we spawned and still own.
1545	            unsafe {
1546	                libc::kill(self.child.id() as libc::pid_t, libc::SIGTERM);
1547	            }
1548	            for _ in 0..30 {
1549	                if matches!(self.child.try_wait(), Ok(Some(_))) {
1550	                    return;
1551	                }
1552	                std::thread::sleep(Duration::from_millis(100));
1553	            }
1554	        }
1555	        let _ = self.child.kill();
1556	        let _ = self.child.wait();
1557	    }
1558	}
1559	
1560	fn spawn_reader<R: std::io::Read + Send + 'static>(
1561	    pipe: R,
1562	    tx: mpsc::Sender<TunnelEvent>,
1563	    log: TunnelLog,
1564	) -> std::thread::JoinHandle<()> {
1565	    std::thread::spawn(move || {
1566	        let mut sent_url = false;
1567	        for line in BufReader::new(pipe).lines() {
1568	            let Ok(line) = line else { break };
1569	            remember_tunnel_line(&log, &line);
1570	            if !sent_url {
1571	                if let Some(u) = parse_tunnel_url(&line) {
1572	                    sent_url = true;
1573	                    let _ = tx.send(TunnelEvent::Url(u));
1574	                    continue;
1575	                }
1576	            }
1577	            if tunnel_line_means_connected(&line) {
1578	                let _ = tx.send(TunnelEvent::Connected);
1579	            }
1580	        }
1581	    })
1582	}
1583	
1584	/// Keep `line` as one of the last [`TUNNEL_LOG_LINES`]; long lines are cut.
1585	fn remember_tunnel_line(log: &TunnelLog, line: &str) {
1586	    let line = line.trim_end();
1587	    if line.is_empty() {
1588	        return;
1589	    }
1590	    let kept: String = line.chars().take(300).collect();
1591	    let mut lines = match log.lock() {
1592	        Ok(l) => l,
1593	        Err(poisoned) => poisoned.into_inner(),
1594	    };
1595	    if lines.len() == TUNNEL_LOG_LINES {
1596	        lines.pop_front();
1597	    }
1598	    lines.push_back(kept);
1599	}
