1	//! Response envelope used by every Xerj Console endpoint.
2	//!
3	//! Every successful response wraps the payload in
4	//!
5	//! ```json
6	//! { "data": <T>, "meta": { "etag": "…", "page": { "next": "…" }, "request_id": "…" } }
7	//! ```
8	//!
9	//! `meta` keys are all optional — the SPA reads them when it needs to
10	//! pin an `If-Match` etag, follow a cursor, or grep server logs by
11	//! request id.
12	
13	use axum::{
14	    http::{HeaderMap, HeaderValue, StatusCode},
15	    response::{IntoResponse, Response},
16	    Json,
17	};
18	use serde::Serialize;
19	use serde_json::{json, Value};
20	
21	#[derive(Debug, Clone, Default, Serialize)]
22	pub struct PageMeta {
23	    #[serde(skip_serializing_if = "Option::is_none")]
24	    pub next: Option<String>,
25	    #[serde(skip_serializing_if = "Option::is_none")]
26	    pub total: Option<u64>,
27	}
28	
29	/// Build a JSON `{ data: …, meta: … }` envelope. Pass `meta = None` for
30	/// endpoints that don't need any meta keys; the field is omitted from the
31	/// body in that case so wire size stays small.
32	pub fn envelope<T: Serialize>(data: T, meta: Option<Value>) -> Value {
33	    match meta {
34	        Some(m) => json!({ "data": data, "meta": m }),
35	        None => json!({ "data": data }),
36	    }
37	}
38	
39	/// Convenience: 200 OK with envelope and an optional `ETag` header.
40	///
41	/// The etag string is wrapped in `W/"…"` per RFC 7232 §2.3 — Xerj Console etags
42	/// are always weak (they reflect the resource version, not byte-level
43	/// equality, and therefore can't satisfy strong-comparison rules).
44	pub fn ok<T: Serialize>(data: T, etag: Option<&str>) -> Response {
45	    let mut headers = HeaderMap::new();
46	    if let Some(e) = etag {
47	        if let Ok(v) = HeaderValue::from_str(&format!("W/\"{e}\"")) {
48	            headers.insert(axum::http::header::ETAG, v);
49	        }
50	    }
51	    let body = if let Some(e) = etag {
52	        envelope(data, Some(json!({ "etag": format!("W/\"{e}\"") })))
53	    } else {
54	        envelope(data, None)
55	    };
56	    (StatusCode::OK, headers, Json(body)).into_response()
57	}
58	
59	/// 201 Created with a `Location` header. Used by `POST` collection endpoints.
60	pub fn created<T: Serialize>(data: T, location: &str, etag: Option<&str>) -> Response {
61	    let mut headers = HeaderMap::new();
62	    if let Ok(v) = HeaderValue::from_str(location) {
63	        headers.insert(axum::http::header::LOCATION, v);
64	    }
65	    if let Some(e) = etag {
66	        if let Ok(v) = HeaderValue::from_str(&format!("W/\"{e}\"")) {
67	            headers.insert(axum::http::header::ETAG, v);
68	        }
69	    }
70	    let body = if let Some(e) = etag {
71	        envelope(data, Some(json!({ "etag": format!("W/\"{e}\"") })))
72	    } else {
73	        envelope(data, None)
74	    };
75	    (StatusCode::CREATED, headers, Json(body)).into_response()
76	}
77	
78	/// 204 No Content — for `DELETE` and idempotent updates with no body.
79	pub fn no_content() -> Response {
80	    StatusCode::NO_CONTENT.into_response()
81	}
