156	  function sha256Hex(ascii) {
157	    const K = [
158	      0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
159	      0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
160	      0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
161	      0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
162	      0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
163	      0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
164	      0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
165	      0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
166	    ];
167	    const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
168	    const rotr = (x, n) => (x >>> n) | (x << (32 - n));
169	    const bytes = [];
170	    for (let i = 0; i < ascii.length; i += 1) bytes.push(ascii.charCodeAt(i) & 0xff);
171	    const bits = bytes.length * 8;
172	    bytes.push(0x80);
173	    while (bytes.length % 64 !== 56) bytes.push(0);
174	    // 64-bit big-endian length. The input is a 32-character id, so the high
175	    // word is always zero.
176	    bytes.push(0, 0, 0, 0, (bits >>> 24) & 0xff, (bits >>> 16) & 0xff, (bits >>> 8) & 0xff, bits & 0xff);
177	    const w = new Array(64);
178	    for (let off = 0; off < bytes.length; off += 64) {
179	      for (let i = 0; i < 16; i += 1) {
180	        const at = off + 4 * i;
181	        w[i] = (bytes[at] << 24) | (bytes[at + 1] << 16) | (bytes[at + 2] << 8) | bytes[at + 3];
182	      }
183	      for (let i = 16; i < 64; i += 1) {
184	        const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
185	        const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
186	        w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
187	      }
188	      let [a, b, c, d, e, f, g, h] = H;
189	      for (let i = 0; i < 64; i += 1) {
190	        const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
191	        const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
192	        h = g; g = f; f = e; e = (d + t1) | 0;
193	        d = c; c = b; b = a; a = (t1 + t2) | 0;
194	      }
195	      [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) | 0; });
196	    }
197	    return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
198	  }
