371	  /** Walk an ES mapping `properties` tree into [{name, type}]. */
372	  function flattenProps(props, prefix, out) {
373	    for (const [name, def] of Object.entries(props || {})) {
374	      if (!def || typeof def !== 'object') continue;
375	      const full = prefix ? `${prefix}.${name}` : name;
376	      if (def.properties) flattenProps(def.properties, full, out);
377	      else if (typeof def.type === 'string') out.push({ name: full, type: def.type });
378	    }
379	    return out;
380	  }
