382	  /**
383	   * One search plan per shared index: which field (if any) is `semantic_text`
384	   * — that is what makes the `hybrid` query available — and which text fields
385	   * a plain `multi_match` should cover.
386	   */
387	  async function learnMappings() {
388	    const indices = String(state.session.index).split(',').map((x) => x.trim()).filter(Boolean);
389	    let mapping = null;
390	    try {
391	      const r = await call('GET', `/${encIndex(state.session.index)}/_mapping`, undefined, true);
392	      if (r.status === 401 || r.status === 403) return accessEnded();
393	      if (r.status === 200) mapping = r.json;
394	    } catch { /* fall through: search without a field list */ }
395	    state.plans = indices.map((index) => {
396	      const props = mapping && mapping[index] && mapping[index].mappings && mapping[index].mappings.properties;
397	      const flat = flattenProps(props, '', []).filter((f) => !f.name.endsWith('_vector'));
398	      const semantic = flat.find((f) => f.type === 'semantic_text');
399	      const texts = flat.filter((f) => f.type === 'text' || f.type === 'semantic_text').map((f) => f.name);
400	      const ordered = [
401	        ...TITLE_FIELDS.filter((f) => texts.includes(f)).map((f) => `${f}^2`),
402	        ...texts.filter((f) => !TITLE_FIELDS.includes(f)),
403	      ].slice(0, MAX_QUERY_FIELDS);
404	      return { index, semanticField: semantic ? semantic.name : null, fields: ordered };
405	    });
406	    const hybrid = state.plans.filter((p) => p.semanticField).length;
407	    $('search-mode').textContent = hybrid === 0
408	      ? 'Keyword search (BM25). Results are ranked by how well the words match.'
409	      : hybrid === state.plans.length
410	        ? 'Hybrid search: keyword matching (BM25) fused with vector similarity from the owner\'s embedder. No text is generated.'
411	        : 'Hybrid search where the index supports it, keyword search elsewhere. No text is generated.';
412	    return undefined;
413	  }
