415	  /**
416	   * The keyword leg. `multi_match` over the text fields the mapping listed,
417	   * titles boosted. With no field list (the mapping could not be read) it is
418	   * `simple_query_string`, which needs none — this engine refuses a
419	   * `multi_match` without `fields`, and `simple_query_string` never throws on
420	   * what a person types.
421	   */
422	  function lexicalQuery(plan, q) {
423	    if (plan.fields.length) return { multi_match: { query: q, fields: plan.fields } };
424	    return { simple_query_string: { query: q } };
425	  }
