427	  function queryFor(plan, q) {
428	    if (!plan.semanticField) return lexicalQuery(plan, q);
429	    return { hybrid: { queries: [
430	      { query: lexicalQuery(plan, q), weight: 1 },
431	      { query: { semantic: { field: plan.semanticField, query: q } }, weight: 1 },
432	    ] } };
433	  }
434	
435	  /**
436	   * Named fields, never `*`: this engine's highlighter does not expand a field
