443	      ? plan.fields.map((f) => f.replace(/\^.*$/, ''))
444	      : [...BODY_FIELDS, ...TITLE_FIELDS];
445	    const fields = {};
446	    for (const name of names) fields[name] = {};
447	    return fields;
448	  }
