450	  function searchBody(plan, q, from) {
451	    return {
452	      from,
453	      size: PAGE_SIZE,
454	      track_total_hits: true,
455	      query: queryFor(plan, q),
456	      _source: { excludes: ['*_vector'] },
457	      highlight: {
458	        pre_tags: [HL_PRE],
459	        post_tags: [HL_POST],
460	        fragment_size: 220,
461	        number_of_fragments: 1,
462	        fields: highlightFields(plan),
463	      },
464	    };
465	  }
