473	  async function runSearch(q, from) {
474	    if (!state.session) return;
475	    if (!state.plans.length) await learnMappings();
476	    if (!state.session) return;
477	    setStatus('Searching…');
478	    const perIndex = [];
479	    try {
480	      // One request per shared index, each with the query its mapping
481	      // supports. Scores from different query types are not comparable, so
482	      // pages are interleaved by rank rather than merged by score.
483	      for (const plan of state.plans) {
484	        const r = await call('POST', `/${encodeURIComponent(plan.index)}/_search`, searchBody(plan, q, from), true);
