486	        if (r.status !== 200 || !r.json || !r.json.hits) {
487	          const reason = r.json && r.json.error && r.json.error.reason;
488	          setStatus(`The search could not be run${reason ? `: ${String(reason).slice(0, 200)}` : ` (HTTP ${r.status})`}.`, true);
