505	    state.terms = termsOf(q);
506	    state.from = from;
507	    state.total = total;
508	    for (const hit of merged) $('results').appendChild(renderHit(hit));
509	    // Which query the list now shows. Until the answer is in, the previous
510	    // list stays on screen, so a reader (or a test) cannot tell a new result
511	    // from an old one by looking at the rows alone.
