1	// ============================================================
2	// XERJ Console — safe DOM construction
3	//
4	// The corpus home and the reader show OTHER PEOPLE'S DOCUMENTS: an email
5	// subject, an attachment filename, a PDF page, a highlight fragment, a graph
6	// node title. Every one of those strings is attacker-controlled (anyone can
7	// mail you `<img src=x onerror=…>` as a subject), and in guest mode the
8	// viewer's API key sits in sessionStorage on this origin — one script
9	// execution is key theft.
10	//
11	// The rest of the console builds HTML strings and relies on `esc()` at every
12	// interpolation. That is correct only while nobody ever forgets one. This
13	// module removes the HTML parser from the path instead:
14	//
15	//   h(tag, attrs, ...children)   a plain-data node. Children are nodes or
16	//                                STRINGS; a string is always text.
17	//   mount(container, nodes)      builds real DOM with createElement /
18	//                                createTextNode / setAttribute only.
19	//
20	// Guarantees, by construction rather than by discipline:
21	//   • no document string is ever parsed as HTML — this file, and everything
22	//     that renders through it, contains no markup-parsing sink at all
23	//     (test/safe-dom.test.mjs greps the sources for the full sink list);
24	//   • tags come from TAGS and attribute names from ATTRS — both closed
25	//     lists, and both are code constants, never data. An unknown tag or
26	//     attribute THROWS, so a typo (or someone "just adding onclick") fails
27	//     the tests instead of shipping;
28	//   • there is no `style`, no `src`, no `srcset`, no `action`, no `on*`;
29	//   • an `href` is kept only when it is an in-app hash route (`#/…`).
30	//     `javascript:`, `data:`, `vbscript:`, `//evil`, `https://…`, a leading
31	//     space or control character — all dropped, leaving an inert <a>. The
32	//     reader never links out: a URL found in a document is shown as text.
33	//
34	// `h` and the helpers are pure (no DOM), so render functions are testable
35	// under node; `mount` needs a Document and is exercised in a real browser
36	// (test/browser/).
37	// ============================================================
38	
39	/** Elements a render function may create. Nothing that loads a resource,
40	 *  runs script, or submits anywhere. */
41	export const TAGS = new Set([
42	  'div', 'span', 'p', 'a', 'h1', 'h2', 'h3', 'h4', 'ul', 'ol', 'li',
43	  'pre', 'code', 'mark', 'article', 'section', 'header', 'footer', 'nav',
44	  'button', 'b', 'strong', 'em', 'small', 'dl', 'dt', 'dd', 'br', 'hr',
45	  'label', 'input', 'select', 'option', 'time',
46	  // The only interactive element added for the knowledge surface: a
47	  // disclosure. It collapses/expands content the browser itself — no
48	  // script, no focus behaviour to get wrong, nothing loads.
49	  'details', 'summary',
50	]);
51	
52	/** Attribute names a render function may set (plus `data-*` / `aria-*`). */
53	export const ATTRS = new Set([
54	  'class', 'href', 'title', 'id', 'role', 'tabindex', 'type', 'name',
55	  'value', 'placeholder', 'for', 'disabled', 'selected', 'autocomplete',
56	  'spellcheck', 'datetime', 'hidden',
57	]);
58	
59	const INPUT_TYPES = new Set(['text', 'search']);
60	const BUTTON_TYPES = new Set(['button']);
61	
62	/** Is this attribute name allowed? `on*` can never pass: it is not in ATTRS
63	 *  and does not start with `data-` / `aria-`. */
64	export function attrAllowed(name) {
65	  if (typeof name !== 'string') return false;
66	  if (ATTRS.has(name)) return true;
67	  return /^(data|aria)-[a-z0-9-]+$/.test(name);
68	}
