70	function hasControlChar(s) {
71	  for (let i = 0; i < s.length; i++) {
72	    const c = s.charCodeAt(i);
73	    if (c < 0x20 || c === 0x7f) return true;
74	  }
75	  return false;
76	}
77	
78	/**
79	 * The only hrefs the console renders from data: in-app hash routes.
80	 * Returns the href when safe, null otherwise.
81	 */
82	export function safeHref(v) {
83	  if (typeof v !== 'string') return null;
84	  // `#/` exactly at position 0 — no leading whitespace/control characters
85	  // (browsers strip those before resolving a scheme) and no scheme at all.
86	  if (!v.startsWith('#/')) return null;
87	  // A fragment cannot change the document's origin or scheme, but keep
88	  // control characters out of attributes on principle.
89	  if (hasControlChar(v)) return null;
90	  return v;
91	}
