93	/** Build a node. `attrs` may be null. Falsy children are skipped; arrays are
94	 *  flattened; anything that is not a node becomes TEXT. */
95	export function h(tag, attrs, ...children) {
96	  if (!TAGS.has(tag)) throw new Error(`safe-dom: tag <${String(tag)}> is not allowed`);
97	  const a = {};
98	  for (const [k, v] of Object.entries(attrs || {})) {
99	    if (v == null || v === false) continue;
100	    if (!attrAllowed(k)) throw new Error(`safe-dom: attribute "${k}" is not allowed`);
101	    // An href must already BE a string: coercing first would let an object
102	    // with a crafted toString() choose the URL.
103	    if (k === 'href' && typeof v !== 'string') continue;
104	    a[k] = v === true ? '' : String(v);
105	  }
106	  if (tag === 'input' && !INPUT_TYPES.has(a.type || 'text')) {
107	    throw new Error(`safe-dom: <input type="${a.type}"> is not allowed`);
108	  }
109	  if (tag === 'button') {
110	    if (a.type && !BUTTON_TYPES.has(a.type)) throw new Error(`safe-dom: <button type="${a.type}"> is not allowed`);
111	    a.type = 'button';
112	  }
113	  if ('href' in a) {
114	    const ok = safeHref(a.href);
115	    if (ok == null) delete a.href; else a.href = ok;
116	  }
117	  const c = [];
118	  const push = (x) => {
119	    if (x == null || x === false || x === true || x === '') return;
120	    if (Array.isArray(x)) { x.forEach(push); return; }
121	    if (isNode(x)) { c.push(x); return; }
122	    c.push(String(x));
123	  };
124	  children.forEach(push);
125	  return { $: 'node', tag, attrs: a, children: c };
126	}
127	
128	export function isNode(x) {
129	  return !!x && typeof x === 'object' && x.$ === 'node' && typeof x.tag === 'string';
130	}
131	
132	/** All text under a node (or list), concatenated — what a person reads. */
133	export function textOf(node) {
134	  if (node == null) return '';
135	  if (Array.isArray(node)) return node.map(textOf).join('');
136	  if (typeof node === 'string') return node;
137	  if (!isNode(node)) return '';
138	  return node.children.map(textOf).join('');
139	}
140	
141	/** Depth-first visit of every element node. */
142	export function walk(node, fn) {
143	  if (Array.isArray(node)) { node.forEach((n) => walk(n, fn)); return; }
144	  if (!isNode(node)) return;
145	  fn(node);
146	  node.children.forEach((c) => walk(c, fn));
147	}
148	
149	/** Every element node matching `pred`, in document order. */
150	export function findAll(node, pred) {
151	  const out = [];
152	  walk(node, (n) => { if (pred(n)) out.push(n); });
153	  return out;
154	}
