    if (!validName(obj.brain)) return null;
    brain = obj.brain;
  }

  const expires_at = expiryMs(obj.expires_at);
  if (expires_at == null || expires_at <= now) return null;

  const label = typeof obj.label === 'string' && obj.label.trim()
    ? obj.label.trim().slice(0, 120)
    : indices.join(', ');
