143	/// Parse one element of an `X-Forwarded-For` chain into an address.
144	///
145	/// Handles the shapes proxies actually emit: a bare address, a bracketed
146	/// IPv6 literal with a port (`[2001:db8::1]:443`), and an IPv4 address with
147	/// a port (`1.2.3.4:5678`). Returns `None` for anything else — including
148	/// RFC 7239 obfuscated identifiers (`_hidden`) and `unknown`, which carry no
149	/// address and must not be silently skipped over.
150	pub fn parse_forwarded_element(raw: &str) -> Option<IpAddr> {
151	    let s = raw.trim();
152	    if s.is_empty() {
153	        return None;
154	    }
155	    // `[v6]:port` or `[v6]`
156	    if let Some(rest) = s.strip_prefix('[') {
157	        let (inner, _) = rest.split_once(']')?;
158	        return inner.parse::<Ipv6Addr>().ok().map(IpAddr::V6);
159	    }
160	    if let Ok(ip) = s.parse::<IpAddr>() {
161	        return Some(ip);
162	    }
163	    // `1.2.3.4:5678` — only valid for v4; a bare v6 with a colon-port is
164	    // ambiguous and proxies are required to bracket it.
165	    if let Some((host, port)) = s.rsplit_once(':') {
166	        if !port.is_empty() && port.bytes().all(|b| b.is_ascii_digit()) {
167	            if let Ok(v4) = host.parse::<Ipv4Addr>() {
168	                return Some(IpAddr::V4(v4));
169	            }
170	        }
171	    }
172	    None
173	}
